    extracted_groups = []  # Initialize an empty list to store the extracted groups

    start = 0
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            start = i
        elif paren_string[i] == ')':
            extracted_groups.append(paren_string[start:i+1])  # Identify and extract each group of nested parentheses

    return extracted_groups  # Return the list of extracted groups

